def publish_reading(sensor, value, notifier):
    if not sensor:
        raise ValueError("sensor is required")
    if value < 0 or value > 100:
        raise ValueError("reading out of range")
    notifier.notify(sensor, value)
    return value

def advance(state, amount):
    state['count'] += amount
    return state['count']

state = {'count': 4}
result = advance(state, 3)
